/*
 * A115659  Permutation of natural numbers generated by 2-rowed array shown
 *          below.
 * https://oeis.org/A115659
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn
 * Formula:   a(1) = 0. For n > 1, * if n mod 4 == 0: a(n) = n * if n mod 4 ==
 *            2: a(n) = n + 1 * if n mod 4 == 3: a(n) = n - 2 * if n mod 4 ==
 *            1: a(n) = n - 3
 * Range:     u8 n <= 65, u16 n <= 65, u32 n <= 65, u64 n <= 65, u128 n <= 65,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n) {
    if (n == 1) {
        return 0;
    }

    seq_t m = (seq_t)n;          /* work in seq_t to avoid overflow */
    switch (n & 3) {              /* n % 4 == n & 3 for unsigned n */
        case 0: return m;        /* a(n) = n                               */
        case 1: return m - 3;    /* a(n) = n - 3                           */
        case 2: return m + 1;    /* a(n) = n + 1                           */
        case 3: return m - 2;    /* a(n) = n - 2                           */
        default: return 0;       /* unreachable */
    }
}
